"use client";

import { useState, useEffect } from "react";
import ProtectedRoute from "@/components/ProtectedRoute";
import { useAuth } from "@/context/AuthContext";
import api from "@/services/api";
import { Activity, Users, CalendarCheck, BrainCircuit, Activity as ActivityIcon } from "lucide-react";
import LabReportAnalyzer from "@/components/doctor/LabReportAnalyzer";
import { SmartDiagnosisModal } from "@/components/doctor/SmartDiagnosisModal";
import { DoctorStats } from "@/components/doctor/DoctorStats";
import { DoctorWaitlist } from "@/components/doctor/DoctorWaitlist";
import { DoctorConsultationModal } from "@/components/doctor/DoctorConsultationModal";

import { Button } from "@/components/ui/button";
import {
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
} from "recharts";

interface Appointment {
    _id: string;
    date: string;
    status: string;
    patientId: { _id: string; name: string; age: number; contact: string };
}

export default function DoctorDashboard() {
    const { user, logout } = useAuth();
    const [appointments, setAppointments] = useState<Appointment[]>([]);

    // Consultation Modal State
    const [activeAppointment, setActiveAppointment] = useState<Appointment | null>(null);
    const [isConsultOpen, setIsConsultOpen] = useState(false);
    
    // UI State
    const [isSmartDiagnosisOpen, setIsSmartDiagnosisOpen] = useState(false);
    const [analytics, setAnalytics] = useState<{ 
        stats?: { dailyAppointments?: number; totalAppointments?: number; totalPrescriptions?: number }; 
        monthlyStats?: { _id: string; count: number }[]; 
    } | null>(null);

    const fetchDashboardData = async () => {
        try {
            const res = await api.get("/appointments");
            // Standardized API might return { success: true, appointments: [...] }
            setAppointments(res.data.success ? res.data.appointments : res.data);
            
            const analyticsRes = await api.get("/doctor/analytics");
            if (analyticsRes.data?.success) {
                setAnalytics(analyticsRes.data);
            }
        } catch (error) {
            console.error("Failed to fetch dashboard data", error);
        }
    };

    useEffect(() => {
        fetchDashboardData();
    }, []);

    const handleOpenConsultation = (apt: Appointment) => {
        setActiveAppointment(apt);
        setIsConsultOpen(true);
    };

    return (
        <>
            <header className="mb-8 flex justify-between items-start">
                <div>
                    <h1 className="text-3xl font-bold text-slate-800 tracking-tight">Active Waitlist</h1>
                    <p className="text-slate-500 mt-1">Select confirmed appointments to begin physical or tele-consultation.</p>
                </div>
                <Button
                    onClick={() => setIsSmartDiagnosisOpen(true)}
                    className="bg-indigo-600 hover:bg-indigo-700 text-white flex items-center gap-2 shadow-md transition-all active:scale-95"
                >
                    <BrainCircuit size={18} />
                    Smart Symptom Checker
                </Button>
            </header>

            {/* Stats Cards extracted to component */}
            <DoctorStats 
                stats={analytics?.stats} 
                confirmedCount={appointments.filter(a => a.status === 'confirmed').length} 
            />

            {/* Chart Row */}
            <div className="mb-8 bg-white rounded-xl shadow-sm border border-slate-200 p-6 transition-all hover:shadow-md">
                 <h2 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
                     <ActivityIcon className="text-indigo-500" size={20} />
                     My Monthly Consultations
                 </h2>
                 {analytics?.monthlyStats && analytics.monthlyStats.length > 0 ? (
                     <ResponsiveContainer width="100%" height={260}>
                         <BarChart data={analytics.monthlyStats.map((m: { _id: string; count: number }) => ({ month: m._id, consults: m.count }))}>
                             <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                             <XAxis dataKey="month" tick={{ fontSize: 12 }} />
                             <YAxis allowDecimals={false} tick={{ fontSize: 12 }} />
                             <Tooltip 
                                contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                                cursor={{ fill: '#f8fafc' }} 
                             />
                             <Bar dataKey="consults" fill="#6366f1" radius={[4, 4, 0, 0]} />
                         </BarChart>
                     </ResponsiveContainer>
                 ) : (
                     <div className="flex flex-col items-center justify-center py-10 text-slate-400">
                         <p className="text-center italic">Not enough historical data to map trends.</p>
                     </div>
                 )}
            </div>

            {/* Waitlist Table extracted to component */}
            <DoctorWaitlist 
                appointments={appointments} 
                onStartConsult={handleOpenConsultation} 
            />

            <LabReportAnalyzer />

            {/* Consultation Modal extracted to component */}
            <DoctorConsultationModal 
                appointment={activeAppointment}
                open={isConsultOpen}
                onOpenChange={setIsConsultOpen}
                onSuccess={fetchDashboardData}
            />

            <SmartDiagnosisModal open={isSmartDiagnosisOpen} onOpenChange={setIsSmartDiagnosisOpen} />
        </>
    );
}

"use client";

import React, { useState } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { useAuth } from "@/context/AuthContext";

import {
    Activity, CalendarCheck, Users, FileText, LogOut, LayoutDashboard, User, Menu, X, FolderHeart
} from "lucide-react";
import { Button } from "@/components/ui/button";
import ProtectedRoute from "@/components/ProtectedRoute";

const sidebarLinks = [
    { href: "/doctor/dashboard", label: "Dashboard", icon: LayoutDashboard },
    { href: "/doctor/patients", label: "My Patients", icon: Users },
    { href: "/doctor/appointments", label: "Schedule", icon: CalendarCheck },
    { href: "/doctor/records", label: "Medical Records", icon: FolderHeart },
    { href: "/doctor/profile", label: "My Profile", icon: User },
];

export default function DoctorLayout({ children }: { children: React.ReactNode }) {
    const { user, logout } = useAuth();
    const pathname = usePathname();
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);

    return (
        <ProtectedRoute allowedRoles={["Doctor"]}>
            <div className="flex h-screen bg-slate-50 overflow-hidden relative">

                {/* Mobile Header */}
                <div className="md:hidden absolute top-0 left-0 right-0 h-16 bg-slate-900 flex items-center justify-between px-4 z-20 shadow-md">
                    <div className="text-xl font-bold flex items-center gap-2 text-white">
                        <Activity className="text-indigo-400" size={24} />
                        AI Clinic
                    </div>
                    <button
                        onClick={() => setIsSidebarOpen(!isSidebarOpen)}
                        className="text-slate-300 hover:text-white focus:outline-none"
                    >
                        {isSidebarOpen ? <X size={28} /> : <Menu size={28} />}
                    </button>
                </div>

                {/* Sidebar */}
                <aside
                    className={`
                        fixed md:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-slate-100 flex flex-col shadow-2xl 
                        transform transition-transform duration-300 ease-in-out
                        ${isSidebarOpen ? "translate-x-0" : "-translate-x-full md:translate-x-0"}
                    `}
                >
                    <div className="h-16 md:h-auto p-6 text-2xl font-bold border-b border-slate-800 flex items-center gap-2">
                        <Activity className="text-indigo-400 hidden md:block" />
                        <span className="hidden md:block">AI Clinic</span>
                        <span className="md:ml-2 text-xs bg-indigo-500/20 text-indigo-400 px-2 py-0.5 rounded">Doctor</span>
                    </div>

                    <nav className="flex-1 p-4 space-y-1.5 mt-2 md:mt-4 overflow-y-auto">
                        {sidebarLinks.map((link) => {
                            const isActive = pathname === link.href;
                            return (
                                <Link
                                    key={link.href}
                                    href={link.href}
                                    onClick={() => setIsSidebarOpen(false)}
                                    className={`flex items-center gap-3 py-3 px-4 rounded-lg transition duration-200 font-medium ${isActive
                                        ? "bg-slate-800/50 text-white border border-slate-700/50 shadow-inner"
                                        : "text-slate-400 hover:bg-slate-800 hover:text-slate-200"
                                        }`}
                                >
                                    <link.icon size={18} className={isActive ? "text-indigo-400" : ""} />
                                    {link.label}
                                </Link>
                            );
                        })}
                    </nav>

                    <div className="p-4 border-t border-slate-800 bg-slate-900 shrink-0">
                        <div className="mb-4 text-sm text-slate-400 px-2">
                            Doctor Portal
                            <span className="font-semibold text-white block mt-1 truncate">Dr. {user?.name}</span>
                        </div>
                        <Button
                            variant="ghost"
                            className="w-full justify-start text-rose-400 hover:text-rose-300 hover:bg-slate-800"
                            onClick={logout}
                        >
                            <LogOut size={16} className="mr-2" />
                            Log Out
                        </Button>
                    </div>
                </aside>

                {/* Main Content */}
                <main className="flex-1 overflow-y-auto w-full pt-16 md:pt-0 p-4 sm:p-6 md:p-10 relative z-0">
                    <div className="max-w-7xl mx-auto">
                        {children}
                    </div>
                </main>
            </div>
        </ProtectedRoute>
    );
}

