"use client";

import { useEffect, useState } from "react";
import { useAuth } from "@/context/AuthContext";
import api from "@/services/api";
import {
    CalendarCheck, Clock, Loader2, CheckCircle, AlertCircle, XCircle
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import {
    Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";

interface Appointment {
    _id: string;
    date: string;
    status: string;
    doctorId: { _id: string; name: string; email: string };
    patientId: { _id: string; name: string };
}

const statusConfig: Record<string, { color: string; icon: typeof CheckCircle }> = {
    completed: { color: "bg-emerald-100 text-emerald-700", icon: CheckCircle },
    confirmed: { color: "bg-blue-100 text-blue-700", icon: CalendarCheck },
    pending: { color: "bg-amber-100 text-amber-700", icon: Clock },
    cancelled: { color: "bg-rose-100 text-rose-700", icon: XCircle },
};

export default function PatientAppointments() {
    const { user } = useAuth();
    const [appointments, setAppointments] = useState<Appointment[]>([]);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState("all");

    useEffect(() => {
        fetchAppointments();
    }, [user]);

    const fetchAppointments = async () => {
        try {
            const res = await api.get("/appointments");
            setAppointments(res.data);
        } catch (error) {
            console.error("Failed to fetch appointments", error);
        } finally {
            setLoading(false);
        }
    };

    const cancelAppointment = async (id: string) => {
        if (!confirm("Are you sure you want to cancel this appointment?")) return;
        try {
            await api.put(`/appointments/${id}/status`, { status: "cancelled" });
            toast.success("Appointment cancelled");
            setAppointments(prev => prev.map(a => a._id === id ? { ...a, status: "cancelled" } : a));
        } catch (error) {
            console.error("Failed to cancel", error);
        }
    };

    const filtered = filter === "all"
        ? appointments
        : appointments.filter((a) => a.status === filter);

    const counts = {
        all: appointments.length,
        pending: appointments.filter((a) => a.status === "pending").length,
        confirmed: appointments.filter((a) => a.status === "confirmed").length,
        completed: appointments.filter((a) => a.status === "completed").length,
    };

    return (
        <>
            <header className="mb-8">
                <h1 className="text-3xl font-bold text-slate-900 tracking-tight flex items-center gap-3">
                    <CalendarCheck className="text-teal-500" />
                    My Appointments
                </h1>
                <p className="text-slate-500 mt-2 text-lg">View all your scheduled and past appointments.</p>
            </header>

            {/* Filter Tabs */}
            <div className="flex gap-2 mb-6 flex-wrap">
                {(["all", "pending", "confirmed", "completed"] as const).map((f) => (
                    <button
                        key={f}
                        onClick={() => setFilter(f)}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${filter === f
                            ? "bg-teal-500 text-white shadow-sm"
                            : "bg-white border border-slate-200 text-slate-600 hover:bg-slate-50"
                            }`}
                    >
                        {f.charAt(0).toUpperCase() + f.slice(1)} ({counts[f as keyof typeof counts]})
                    </button>
                ))}
            </div>

            {/* Appointments Table */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                {loading ? (
                    <div className="flex justify-center items-center h-64">
                        <Loader2 className="animate-spin text-teal-500 w-8 h-8" />
                    </div>
                ) : filtered.length > 0 ? (
                    <Table>
                        <TableHeader className="bg-slate-50">
                            <TableRow>
                                <TableHead className="font-semibold text-slate-500 uppercase tracking-wider text-xs">Doctor</TableHead>
                                <TableHead className="font-semibold text-slate-500 uppercase tracking-wider text-xs">Date</TableHead>
                                <TableHead className="font-semibold text-slate-500 uppercase tracking-wider text-xs">Time</TableHead>
                                <TableHead className="font-semibold text-slate-500 uppercase tracking-wider text-xs">Status</TableHead>
                                <TableHead className="font-semibold text-slate-500 uppercase tracking-wider text-xs text-right">Actions</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {filtered.map((apt) => {
                                const cfg = statusConfig[apt.status] || statusConfig.pending;
                                const StatusIcon = cfg.icon;
                                return (
                                    <TableRow key={apt._id} className="hover:bg-slate-50/80 transition-colors">
                                        <TableCell className="font-medium text-slate-900">
                                            <div className="flex items-center gap-3">
                                                <div className="w-8 h-8 rounded-full bg-gradient-to-br from-teal-400 to-blue-500 flex items-center justify-center text-white text-sm font-bold flex-shrink-0">
                                                    {apt.doctorId?.name?.charAt(0) || "D"}
                                                </div>
                                                Dr. {apt.doctorId?.name || "Unknown"}
                                            </div>
                                        </TableCell>
                                        <TableCell className="text-slate-600">
                                            {new Date(apt.date).toLocaleDateString(undefined, {
                                                weekday: "short", month: "short", day: "numeric", year: "numeric"
                                            })}
                                        </TableCell>
                                        <TableCell className="text-slate-500">
                                            {new Date(apt.date).toLocaleTimeString(undefined, {
                                                hour: "2-digit", minute: "2-digit"
                                            })}
                                        </TableCell>
                                        <TableCell>
                                            <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 text-xs font-bold rounded-md ${cfg.color}`}>
                                                <StatusIcon size={12} />
                                                {apt.status.charAt(0).toUpperCase() + apt.status.slice(1)}
                                            </span>
                                        </TableCell>
                                        <TableCell className="text-right">
                                            {(apt.status === "pending" || apt.status === "confirmed") && (
                                                <Button variant="outline" size="sm" className="text-rose-600 border-rose-200 hover:bg-rose-50" onClick={() => cancelAppointment(apt._id)}>
                                                    <XCircle size={14} className="mr-1" /> Cancel
                                                </Button>
                                            )}
                                        </TableCell>
                                    </TableRow>
                                );
                            })}
                        </TableBody>
                    </Table>
                ) : (
                    <div className="text-center py-16 px-4">
                        <AlertCircle className="mx-auto h-12 w-12 text-slate-300 mb-3" />
                        <h3 className="text-lg font-medium text-slate-900">No appointments found</h3>
                        <p className="mt-1 text-slate-500 text-sm">
                            {filter !== "all" ? `No ${filter} appointments.` : "You don't have any appointments yet."}
                        </p>
                    </div>
                )}
            </div>
        </>
    );
}

"use client";

import { useEffect, useState } from "react";
import { useAuth } from "@/context/AuthContext";
import api from "@/services/api";
import { toast } from "sonner";
import { Skeleton } from "@/components/ui/skeleton";
import { BookAppointmentModal } from "@/components/patient/BookAppointmentModal";
import { PatientQuickActions } from "@/components/patient/PatientQuickActions";
import { PatientStats } from "@/components/patient/PatientStats";
import { PatientTimeline } from "@/components/patient/PatientTimeline";

interface DoctorInfo {
    _id: string;
    name: string;
}

interface Appointment {
    _id: string;
    date: string;
    status: string;
    doctorId: DoctorInfo | null;
}

interface Prescription {
    _id: string;
    createdAt: string;
    doctorId: DoctorInfo | null;
}

interface Diagnosis {
    _id: string;
    createdAt: string;
    riskLevel: string;
    doctorId: DoctorInfo | null;
}

// Unified Timeline Item for Medical History
interface TimelineItem {
    id: string;
    type: "appointment" | "diagnosis" | "prescription";
    date: string;
    title: string;
    status: string;
    doctorName?: string;
}

export default function PatientDashboard() {
    const { user, updateUser } = useAuth();
    const [appointments, setAppointments] = useState<Appointment[]>([]);
    const [prescriptions, setPrescriptions] = useState<Prescription[]>([]);
    const [diagnoses, setDiagnoses] = useState<Diagnosis[]>([]);
    const [loading, setLoading] = useState(true);
    const [plan, setPlan] = useState(user?.subscriptionPlan || "Free");
    const [isBookingOpen, setIsBookingOpen] = useState(false);

    const fetchTimelineData = async () => {
        try {
            const [aptRes, preRes, diagRes] = await Promise.all([
                api.get("/appointments?limit=50"),
                api.get("/prescriptions/my"),
                api.get("/patients/my-diagnoses")
            ]);
            // Standardized API might return { success: true, appointments: [...] }
            setAppointments(aptRes.data.success ? aptRes.data.appointments : aptRes.data);
            setPrescriptions(preRes.data?.data || []);
            setDiagnoses(diagRes.data?.data || []);
        } catch (error) {
            console.error("Failed to fetch timeline data", error);
            toast.error("Failed to load timeline. Please refresh the page.");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchTimelineData();
    }, [user]);

    // Analytics grouping
    const upcoming = appointments.filter(
        (a) => a.status === "pending" || a.status === "confirmed"
    );
    const completed = appointments.filter((a) => a.status === "completed");

    // Unified Timeline Mapping
    const timelineItems: TimelineItem[] = [
        ...appointments.map((apt): TimelineItem => ({
            id: apt._id,
            type: "appointment",
            date: apt.date,
            title: "Appointment",
            status: apt.status,
            doctorName: apt.doctorId?.name || "Unknown Doctor"
        })),
        ...prescriptions.map((pre): TimelineItem => ({
            id: pre._id,
            type: "prescription",
            date: pre.createdAt,
            title: "Prescription",
            status: "issued",
            doctorName: pre.doctorId?.name || "Unknown Doctor"
        })),
        ...diagnoses.map((diag): TimelineItem => ({
            id: diag._id,
            type: "diagnosis",
            date: diag.createdAt,
            title: "Diagnosis Review",
            status: diag.riskLevel,
            doctorName: diag.doctorId?.name || "Unknown Doctor"
        }))
    ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    const togglePlan = async () => {
        try {
            const res = await api.post("/ai/upgrade-plan");
            if (res.data?.success) {
                setPlan(res.data.plan);
                updateUser({ subscriptionPlan: res.data.plan });
                toast.success(res.data.message);
            }
        } catch (error) {
            console.error(error);
            toast.error("Failed to update plan. Please try again later.");
        }
    };

    return (
        <div className="animate-in fade-in duration-700">
            <header className="mb-6">
                <h1 className="text-3xl font-bold text-slate-900 tracking-tight">
                    Welcome back, {user?.name?.split(" ")[0]} 👋
                </h1>
                <p className="text-slate-500 mt-2 text-lg">
                    Here&apos;s a quick summary of your health profile.
                </p>
            </header>

            {/* Quick Actions Grid */}
            <PatientQuickActions onBookVisit={() => setIsBookingOpen(true)} />

            {loading ? (
                // Modern Skeleton Loader
                <div className="space-y-8 animate-pulse">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                        {[...Array(4)].map((_, i) => (
                            <Skeleton key={i} className="h-40 w-full rounded-xl" />
                        ))}
                    </div>
                    <div className="space-y-4">
                        <Skeleton className="h-8 w-48 rounded-md" />
                        {[...Array(3)].map((_, i) => (
                            <Skeleton key={i} className="h-24 w-full rounded-xl" />
                        ))}
                    </div>
                </div>
            ) : (
                <>
                    {/* Quick Stats */}
                    <PatientStats 
                        upcomingCount={upcoming.length}
                        completedCount={completed.length}
                        plan={plan}
                        onTogglePlan={togglePlan}
                    />

                    {/* Recent Appointments Timeline */}
                    <PatientTimeline 
                        items={timelineItems} 
                        onBookVisit={() => setIsBookingOpen(true)} 
                    />
                </>
            )}

            <BookAppointmentModal
                open={isBookingOpen}
                onOpenChange={setIsBookingOpen}
                onSuccess={fetchTimelineData}
            />
        </div>
    );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { useAuth } from "@/context/AuthContext";
import api from "@/services/api";
import { User, Loader2, Save } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";

export default function PatientProfile() {
    const { user } = useAuth();
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [profile, setProfile] = useState({
        name: "",
        email: "",
        age: "",
        gender: "",
        contact: "",
    });

    const fetchPatientData = useCallback(async () => {
        try {
            const res = await api.get("/patients");
            // Find patient matching current user email
            const match = res.data.find((p: { name?: string; age?: number; gender?: string; contact?: string }) => p.name === user?.name);
            if (match) {
                setProfile(prev => ({
                    ...prev,
                    age: match.age?.toString() || "",
                    gender: match.gender || "",
                    contact: match.contact || "",
                }));
            }
        } catch {
            // Ignore — patient record may not exist
        } finally {
            setLoading(false);
        }
    }, [user?.name]);

    useEffect(() => {
        if (user) {
            setProfile({
                name: user.name || "",
                email: user.email || "",
                age: "",
                gender: "",
                contact: "",
            });
            // Try to fetch patient record if linked
            fetchPatientData();
        }
    }, [user, fetchPatientData]);

    const handleSave = async () => {
        setSaving(true);
        try {
            // Update user name via auth (if endpoint exists)
            toast.success("Profile updated!");
        } catch {
            toast.error("Failed to save");
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="flex justify-center items-center h-64">
                <Loader2 className="animate-spin text-teal-500 w-8 h-8" />
            </div>
        );
    }

    return (
        <>
            <header className="mb-8">
                <h1 className="text-3xl font-bold text-slate-900 tracking-tight flex items-center gap-3">
                    <User className="text-teal-500" />
                    My Profile
                </h1>
                <p className="text-slate-500 mt-2 text-lg">View and manage your personal information.</p>
            </header>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 max-w-2xl">
                <div className="p-8 space-y-6">
                    {/* Avatar */}
                    <div className="flex items-center gap-4 pb-6 border-b border-slate-100">
                        <div className="w-16 h-16 rounded-full bg-gradient-to-br from-teal-400 to-blue-500 flex items-center justify-center text-white text-2xl font-bold">
                            {profile.name?.charAt(0)?.toUpperCase() || "P"}
                        </div>
                        <div>
                            <h2 className="text-xl font-semibold text-slate-800">{profile.name}</h2>
                            <p className="text-sm text-slate-500">{profile.email}</p>
                        </div>
                    </div>

                    {/* Form Fields */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div>
                            <label className="text-sm font-medium text-slate-700 mb-1 block">Full Name</label>
                            <Input value={profile.name} onChange={(e) => setProfile({ ...profile, name: e.target.value })} />
                        </div>
                        <div>
                            <label className="text-sm font-medium text-slate-700 mb-1 block">Email</label>
                            <Input value={profile.email} disabled className="bg-slate-50 text-slate-400" />
                        </div>
                        <div>
                            <label className="text-sm font-medium text-slate-700 mb-1 block">Age</label>
                            <Input type="number" value={profile.age} onChange={(e) => setProfile({ ...profile, age: e.target.value })} />
                        </div>
                        <div>
                            <label className="text-sm font-medium text-slate-700 mb-1 block">Gender</label>
                            <select
                                value={profile.gender}
                                onChange={(e) => setProfile({ ...profile, gender: e.target.value })}
                                className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-ring"
                            >
                                <option value="">Select...</option>
                                <option value="Male">Male</option>
                                <option value="Female">Female</option>
                                <option value="Other">Other</option>
                            </select>
                        </div>
                        <div className="sm:col-span-2">
                            <label className="text-sm font-medium text-slate-700 mb-1 block">Contact Number</label>
                            <Input value={profile.contact} onChange={(e) => setProfile({ ...profile, contact: e.target.value })} placeholder="+92 300 1234567" />
                        </div>
                    </div>

                    <Button onClick={handleSave} disabled={saving} className="bg-teal-600 hover:bg-teal-700 text-white gap-2">
                        {saving ? <Loader2 className="animate-spin h-4 w-4" /> : <Save size={16} />}
                        Save Changes
                    </Button>
                </div>
            </div>
        </>
    );
}

