"use client";

import React, { useState, useEffect } from "react";
import { 
    Users, 
    Search, 
    UserPlus, 
    MoreVertical, 
    Mail, 
    Phone, 
    Calendar,
    ArrowUpRight,
    Loader2,
    Edit,
    Trash2,
    Eye
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import api from "@/services/api";
import { toast } from "sonner";
import {
    Card,
    CardContent,
    CardHeader,
    CardTitle,
} from "@/components/ui/card";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";

interface Patient {
    _id: string;
    name: string;
    age: number;
    gender: string;
    contact: string;
}

export default function ReceptionistPatientsPage() {
    const [patients, setPatients] = useState<Patient[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState("");

    useEffect(() => {
        fetchPatients();
    }, []);

    const fetchPatients = async () => {
        try {
            const res = await api.get("/patients");
            if (res.data.success) {
                setPatients(res.data.patients);
            }
        } catch (error) {
            console.error(error);
            toast.error("Failed to fetch patients");
        } finally {
            setLoading(false);
        }
    };

    const filteredPatients = patients.filter(p => 
        p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.contact.includes(searchQuery)
    );

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-slate-900 tracking-tight">Patient Management</h1>
                    <p className="text-slate-500 mt-1">Register new patients and manage their clinical profiles.</p>
                </div>
                <div className="flex gap-3">
                    <Button className="bg-blue-600 hover:bg-blue-700 h-11 px-6 font-bold shadow-lg shadow-blue-200">
                        <UserPlus size={18} className="mr-2" />
                        Register New Patient
                    </Button>
                </div>
            </div>

            {/* Main Content Card */}
            <Card className="border-slate-200 shadow-xl shadow-slate-200/50 bg-white">
                <CardHeader className="p-8 border-b border-slate-100 bg-slate-50/50">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                        <div className="flex items-center gap-4">
                            <div className="h-10 w-10 bg-blue-100 rounded-lg flex items-center justify-center text-blue-600 font-black">
                                {patients.length}
                            </div>
                            <CardTitle className="text-xl">Active Patients</CardTitle>
                        </div>
                        <div className="relative w-full md:w-96 group">
                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" size={20} />
                            <Input 
                                placeholder="Search by name, contact, or ID..." 
                                className="pl-12 h-11 bg-white border-slate-200 focus:border-blue-500 shadow-sm"
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                            />
                        </div>
                    </div>
                </CardHeader>
                <CardContent className="p-0">
                    {loading ? (
                        <div className="h-64 flex flex-col items-center justify-center gap-4 text-slate-400">
                            <Loader2 className="animate-spin h-8 w-8 text-blue-500" />
                            <p>Syncing patient database...</p>
                        </div>
                    ) : filteredPatients.length > 0 ? (
                        <Table>
                            <TableHeader>
                                <TableRow className="bg-slate-50/50 hover:bg-slate-50/50">
                                    <TableHead className="w-[300px] font-bold py-5 pl-8 uppercase tracking-wider text-[11px] text-slate-400">Patient Details</TableHead>
                                    <TableHead className="font-bold uppercase tracking-wider text-[11px] text-slate-400">Age / Gender</TableHead>
                                    <TableHead className="font-bold uppercase tracking-wider text-[11px] text-slate-400">Contact Info</TableHead>
                                    <TableHead className="font-bold uppercase tracking-wider text-[11px] text-slate-400">Status</TableHead>
                                    <TableHead className="text-right font-bold py-5 pr-8 uppercase tracking-wider text-[11px] text-slate-400">Actions</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {filteredPatients.map((patient) => (
                                    <TableRow key={patient._id} className="group hover:bg-blue-50/30 transition-colors">
                                        <TableCell className="py-5 pl-8">
                                            <div className="flex items-center gap-4">
                                                <div className="h-10 w-10 bg-slate-100 rounded-lg flex items-center justify-center text-slate-600 font-bold group-hover:bg-blue-100 group-hover:text-blue-600 transition-colors">
                                                    {patient.name.charAt(0)}
                                                </div>
                                                <div>
                                                    <div className="font-bold text-slate-900 text-base">{patient.name}</div>
                                                    <div className="text-xs text-slate-400 font-medium">ID: {patient._id.slice(-8).toUpperCase()}</div>
                                                </div>
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            <div className="text-slate-700 font-medium">{patient.age} Yrs</div>
                                            <div className="text-xs text-slate-500">{patient.gender}</div>
                                        </TableCell>
                                        <TableCell>
                                            <div className="flex items-center gap-2 text-slate-600">
                                                <Mail size={14} className="text-slate-300" />
                                                <span className="text-sm">{patient.contact}</span>
                                            </div>
                                            <div className="flex items-center gap-2 text-slate-600 mt-1">
                                                <Phone size={14} className="text-slate-300" />
                                                <span className="text-sm">+1 234 567 890</span>
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-emerald-100 text-emerald-700 border border-emerald-200 uppercase tracking-tight">
                                                Active
                                            </span>
                                        </TableCell>
                                        <TableCell className="text-right py-5 pr-8">
                                            <div className="flex justify-end gap-1">
                                                <Button variant="ghost" size="icon" className="h-9 w-9 text-slate-400 hover:text-blue-600 hover:bg-blue-50">
                                                    <Eye size={18} />
                                                </Button>
                                                <Button variant="ghost" size="icon" className="h-9 w-9 text-slate-400 hover:text-blue-600 hover:bg-blue-50">
                                                    <Edit size={18} />
                                                </Button>
                                                <Button variant="ghost" size="icon" className="h-9 w-9 text-slate-400 hover:text-rose-600 hover:bg-rose-50">
                                                    <Trash2 size={18} />
                                                </Button>
                                            </div>
                                        </TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </Table>
                    ) : (
                        <div className="h-96 flex flex-col items-center justify-center text-slate-400 p-8 text-center">
                            <div className="h-20 w-20 bg-slate-50 rounded-full flex items-center justify-center mb-6">
                                <Users size={40} className="text-slate-200" />
                            </div>
                            <h3 className="text-xl font-bold text-slate-600 mb-2">No patients found</h3>
                            <p className="max-w-xs text-sm leading-relaxed">
                                No records match your current search criteria.
                            </p>
                        </div>
                    )}
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState } from "react";
import { useAuth } from "@/context/AuthContext";
import { User, Loader2, Save, Mail, MapPin, Phone, ShieldCheck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import {
    Card,
    CardContent,
    CardDescription,
    CardHeader,
    CardTitle,
} from "@/components/ui/card";

export default function ReceptionistProfilePage() {
    const { user } = useAuth();
    const [saving, setSaving] = useState(false);
    const [profile, setProfile] = useState({
        name: user?.name || "",
        email: user?.email || "",
        role: "Front Desk Coordinator",
        department: "Patient Relations",
        contact: "+1 (555) 000-1234",
        location: "Main Wing, Floor 1",
    });

    const handleSave = async () => {
        setSaving(true);
        try {
            await new Promise(resolve => setTimeout(resolve, 800));
            toast.success("Receptionist profile updated!");
        } catch {
            toast.error("Failed to save changes");
        } finally {
            setSaving(false);
        }
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            {/* Header */}
            <div>
                <h1 className="text-3xl font-bold text-slate-900 tracking-tight flex items-center gap-3">
                    <User className="text-blue-500" />
                    Staff Profile
                </h1>
                <p className="text-slate-500 mt-2 text-lg">Manage your personal information and desk location.</p>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                
                {/* Left Column: ID Card */}
                <div className="lg:col-span-1 space-y-6">
                    <Card className="border-none shadow-xl shadow-slate-200/50 bg-white overflow-hidden">
                        <div className="h-24 bg-blue-600" />
                        <CardContent className="relative pt-0 flex flex-col items-center">
                            <div className="relative -mt-12 mb-4">
                                <div className="w-24 h-24 rounded-2xl bg-white p-1.5 shadow-lg">
                                    <div className="w-full h-full rounded-xl bg-slate-50 flex items-center justify-center text-blue-600 text-3xl font-black border border-slate-100 uppercase">
                                        {profile.name?.charAt(0)}
                                    </div>
                                </div>
                            </div>
                            <h2 className="text-xl font-bold text-slate-900">{profile.name}</h2>
                            <p className="text-blue-600 text-sm font-semibold uppercase tracking-wider">{profile.role}</p>
                            
                            <div className="w-full mt-8 space-y-3">
                                <div className="flex items-center gap-3 text-sm text-slate-600">
                                    <Mail size={14} className="text-slate-400" />
                                    <span className="truncate">{profile.email}</span>
                                </div>
                                <div className="flex items-center gap-3 text-sm text-slate-600">
                                    <MapPin size={14} className="text-slate-400" />
                                    <span>{profile.location}</span>
                                </div>
                            </div>
                        </CardContent>
                    </Card>

                    <Card className="bg-blue-50 border-blue-100">
                        <CardContent className="p-4 flex gap-4 items-center">
                            <div className="h-10 w-10 rounded-full bg-white flex items-center justify-center shadow-sm">
                                <ShieldCheck size={20} className="text-blue-600" />
                            </div>
                            <div>
                                <h4 className="text-sm font-bold text-blue-900">Verified Staff</h4>
                                <p className="text-xs text-blue-700">Authorized Front Desk Access</p>
                            </div>
                        </CardContent>
                    </Card>
                </div>

                {/* Right Column: Edit Form */}
                <Card className="lg:col-span-2 border-slate-200 bg-white shadow-sm">
                    <CardHeader className="p-8 border-b border-slate-50">
                        <CardTitle className="text-xl">Account Settings</CardTitle>
                        <CardDescription>Update your contact details and office information.</CardDescription>
                    </CardHeader>
                    <CardContent className="p-8 space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Full Name</label>
                                <Input value={profile.name} onChange={(e) => setProfile({ ...profile, name: e.target.value })} className="h-11 bg-slate-50/50" />
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Email Address</label>
                                <Input value={profile.email} disabled className="h-11 bg-slate-100 text-slate-400 cursor-not-allowed" />
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Contact Number</label>
                                <Input value={profile.contact} onChange={(e) => setProfile({ ...profile, contact: e.target.value })} className="h-11 bg-slate-50/50" />
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Department</label>
                                <Input value={profile.department} onChange={(e) => setProfile({ ...profile, department: e.target.value })} className="h-11 bg-slate-50/50" />
                            </div>
                            <div className="md:col-span-2 space-y-2">
                                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Office Location</label>
                                <Input value={profile.location} onChange={(e) => setProfile({ ...profile, location: e.target.value })} className="h-11 bg-slate-50/50" />
                            </div>
                        </div>

                        <div className="pt-8 flex justify-end">
                            <Button 
                                onClick={handleSave} 
                                disabled={saving} 
                                className="bg-slate-900 hover:bg-slate-800 h-11 px-8 font-bold gap-2 text-sm uppercase tracking-wider transition-all active:scale-95"
                            >
                                {saving ? <Loader2 className="animate-spin h-4 w-4" /> : <Save size={18} />}
                                Update Profile
                            </Button>
                        </div>
                    </CardContent>
                </Card>
            </div>
        </div>
    );
}

