"use client";

import { useState, useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { format } from "date-fns";
import api from "@/services/api";
import { toast } from "sonner";
import { CalendarIcon, Loader2, UserRound, Clock } from "lucide-react";

import { Button } from "@/components/ui/button";
import { CompleteProfileModal } from "@/components/patient/CompleteProfileModal";
import { Calendar } from "@/components/ui/calendar";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    Form,
    FormControl,
    FormField,
    FormItem,
    FormLabel,
    FormMessage,
} from "@/components/ui/form";
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { ScrollArea } from "@/components/ui/scroll-area";

interface Doctor {
    _id: string;
    name: string;
    email: string;
}

const formSchema = z.object({
    doctorId: z.string({
        message: "Please select a doctor.",
    }).min(1, "Please select a doctor."),
    date: z.date({
        message: "Please select a date and time.",
    }).refine((date) => date > new Date(), {
        message: "Appointment time must be in the future.",
    }),
});

interface BookAppointmentModalProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSuccess?: () => void;
}

// Generate available time slots (e.g., 9 AM to 5 PM, every 30 mins)
const generateTimeSlots = () => {
    const slots = [];
    for (let hour = 9; hour <= 17; hour++) {
        for (const minute of [0, 30]) {
            const timeString = `${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`;
            slots.push(timeString);
        }
    }
    return slots;
};

const TIME_SLOTS = generateTimeSlots();

export function BookAppointmentModal({ open, onOpenChange, onSuccess }: BookAppointmentModalProps) {
    const [doctors, setDoctors] = useState<Doctor[]>([]);
    const [loadingDoctors, setLoadingDoctors] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);

    const form = useForm<z.infer<typeof formSchema>>({
        resolver: zodResolver(formSchema),
    });

    useEffect(() => {
        if (open) {
            fetchDoctors();
            form.reset();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [open]);

    const fetchDoctors = async () => {
        setLoadingDoctors(true);
        try {
            const response = await api.get("/users/doctors");
            setDoctors(response.data);
        } catch (error) {
            console.error("Failed to fetch doctors:", error);
            toast.error("Could not load available doctors.");
        } finally {
            setLoadingDoctors(false);
        }
    };

    const onSubmit = async (values: z.infer<typeof formSchema>) => {
        setIsSubmitting(true);
        try {
            // SEC: patientId is intentionally NOT sent. Backend derives it from JWT.
            await api.post("/appointments", {
                doctorId: values.doctorId,
                date: values.date.toISOString(),
            });

            toast.success("Appointment booked successfully!");
            onOpenChange(false);
            if (onSuccess) onSuccess();
        } catch (error: unknown) {
            console.error("Booking failed:", error);
            const axiosErr = error as { response?: { status?: number; data?: { message?: string } } };
            if (axiosErr.response?.status === 404 && axiosErr.response?.data?.message === 'Patient profile incomplete') {
                setIsProfileModalOpen(true);
            } else {
                toast.error(axiosErr.response?.data?.message || "Failed to book appointment.");
            }
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <>
            <Dialog open={open} onOpenChange={onOpenChange}>
                <DialogContent className="sm:max-w-[425px]">
                <DialogHeader>
                    <DialogTitle className="text-2xl font-bold flex items-center gap-2">
                        <CalendarIcon className="w-6 h-6 text-teal-600" />
                        Book a Visit
                    </DialogTitle>
                    <DialogDescription>
                        Select a specialist and your preferred time for the consultation.
                    </DialogDescription>
                </DialogHeader>

                <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6 mt-4">

                        {/* Doctor Selection */}
                        <FormField
                            control={form.control}
                            name="doctorId"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Select Doctor</FormLabel>
                                    <Select onValueChange={field.onChange} defaultValue={field.value}>
                                        <FormControl>
                                            <SelectTrigger className={cn("w-full", !field.value && "text-muted-foreground")}>
                                                <div className="flex items-center gap-2">
                                                    <UserRound className="w-4 h-4 opacity-50" />
                                                    <SelectValue placeholder={loadingDoctors ? "Loading..." : "Choose a specialist"} />
                                                </div>
                                            </SelectTrigger>
                                        </FormControl>
                                        <SelectContent>
                                            {doctors.map((doctor) => (
                                                <SelectItem key={doctor._id} value={doctor._id}>
                                                    Dr. {doctor.name}
                                                </SelectItem>
                                            ))}
                                            {doctors.length === 0 && !loadingDoctors && (
                                                <div className="p-2 text-sm text-slate-500 text-center">No doctors available.</div>
                                            )}
                                        </SelectContent>
                                    </Select>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        {/* Date and Time Selection */}
                        <FormField
                            control={form.control}
                            name="date"
                            render={({ field }) => (
                                <FormItem className="flex flex-col">
                                    <FormLabel>Date & Time</FormLabel>
                                    <Popover>
                                        <PopoverTrigger asChild>
                                            <FormControl>
                                                <Button
                                                    variant={"outline"}
                                                    className={cn(
                                                        "w-full pl-3 text-left font-normal",
                                                        !field.value && "text-muted-foreground"
                                                    )}
                                                >
                                                    {field.value ? (
                                                        format(field.value, "PPP 'at' h:mm a")
                                                    ) : (
                                                        <span>Pick a date and time</span>
                                                    )}
                                                    <CalendarIcon className="ml-auto h-4 w-4 opacity-50" />
                                                </Button>
                                            </FormControl>
                                        </PopoverTrigger>
                                        <PopoverContent className="w-auto p-0 flex align-start" align="start">
                                            {/* Calendar Picker */}
                                            <Calendar
                                                mode="single"
                                                selected={field.value}
                                                onSelect={(date) => {
                                                    // Preserve time if already selected, otherwise set to 9:00 AM
                                                    if (date) {
                                                        const newDate = new Date(date);
                                                        if (field.value) {
                                                            newDate.setHours(field.value.getHours(), field.value.getMinutes());
                                                        } else {
                                                            newDate.setHours(9, 0, 0, 0);
                                                        }
                                                        field.onChange(newDate);
                                                    }
                                                }}
                                                disabled={(date) =>
                                                    date < new Date(new Date().setHours(0, 0, 0, 0))
                                                }
                                                initialFocus
                                            />
                                            {/* Time Picker */}
                                            <div className="border-l border-slate-200 p-3 w-[120px]">
                                                <div className="text-sm font-medium mb-2 flex items-center gap-1.5 text-slate-700">
                                                    <Clock className="w-4 h-4" /> Time
                                                </div>
                                                <ScrollArea className="h-[220px]">
                                                    <div className="flex flex-col gap-1 pr-3">
                                                        {TIME_SLOTS.map((time) => {
                                                            const [hours, minutes] = time.split(':').map(Number);
                                                            const isSelected = field.value &&
                                                                field.value.getHours() === hours &&
                                                                field.value.getMinutes() === minutes;

                                                            return (
                                                                <Button
                                                                    key={time}
                                                                    type="button"
                                                                    variant={isSelected ? "default" : "ghost"}
                                                                    size="sm"
                                                                    className={cn("justify-start font-normal", isSelected && "bg-teal-600 hover:bg-teal-700")}
                                                                    onClick={() => {
                                                                        if (field.value) {
                                                                            const newDate = new Date(field.value);
                                                                            newDate.setHours(hours, minutes, 0, 0);
                                                                            field.onChange(newDate);
                                                                        } else {
                                                                            // If no date selected yet, use today but warn
                                                                            const today = new Date();
                                                                            today.setHours(hours, minutes, 0, 0);
                                                                            field.onChange(today);
                                                                            toast.info("Please select a date on the calendar as well.");
                                                                        }
                                                                    }}
                                                                >
                                                                    {format(new Date().setHours(hours, minutes), "h:mm a")}
                                                                </Button>
                                                            );
                                                        })}
                                                    </div>
                                                </ScrollArea>
                                            </div>
                                        </PopoverContent>
                                    </Popover>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <Button
                            type="submit"
                            className="w-full bg-teal-600 hover:bg-teal-700 text-white"
                            disabled={isSubmitting}
                        >
                            {isSubmitting ? (
                                <>
                                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                    Confirming...
                                </>
                            ) : (
                                "Confirm Booking"
                            )}
                        </Button>
                    </form>
                </Form>
            </DialogContent>
        </Dialog>

        <CompleteProfileModal
            open={isProfileModalOpen}
            onOpenChange={setIsProfileModalOpen}
            onSuccess={() => {
                // Retry booking automatically once profile is created
                const values = form.getValues();
                if (values.doctorId && values.date) {
                    onSubmit(values);
                }
            }}
        />
        </>
    );
}

"use client";

import { useState, useRef, useEffect, useCallback } from "react";
import api from "@/services/api";
import { MessageCircle, X, Send, Loader2, Bot, User, Clock, RefreshCw } from "lucide-react";
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';

interface ChatMessage {
    role: "user" | "ai";
    content: string;
    retryable?: boolean;
    retryPrompt?: string;
}

export default function HealthChatbot() {
    const [isOpen, setIsOpen] = useState(false);
    const [messages, setMessages] = useState<ChatMessage[]>([
        { role: "ai", content: "Hi! 👋 I'm your personal health assistant. I can answer questions about your prescriptions, appointments, and medicines. How can I help you today?" },
    ]);
    const [input, setInput] = useState("");
    const [isLoading, setIsLoading] = useState(false);
    const [countdown, setCountdown] = useState(0);
    const [lastFailedMessage, setLastFailedMessage] = useState<string | null>(null);
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const countdownRef = useRef<ReturnType<typeof setInterval> | null>(null);

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }, [messages]);

    // Countdown timer
    useEffect(() => {
        if (countdown > 0) {
            countdownRef.current = setInterval(() => {
                setCountdown(prev => {
                    if (prev <= 1) {
                        if (countdownRef.current) clearInterval(countdownRef.current);
                        return 0;
                    }
                    return prev - 1;
                });
            }, 1000);
        }
        return () => {
            if (countdownRef.current) clearInterval(countdownRef.current);
        };
    }, [countdown]);

    const sendMessage = useCallback(async (messageText?: string) => {
        const trimmed = (messageText || input).trim();
        if (!trimmed || isLoading) return;

        // Create new history array with the user's latest message
        const nextMessages = [...messages.filter(m => !m.retryable)];
        
        if (!messageText) {
            nextMessages.push({ role: "user", content: trimmed });
            setInput("");
        }
        
        setMessages(nextMessages);
        setIsLoading(true);
        setLastFailedMessage(null);

        try {
            const token = localStorage.getItem('clinicToken');
            const baseURL = process.env.NEXT_PUBLIC_API_URL || 'https://ai-clinic-backend.onrender.com/api/v1';
            
            const response = await fetch(`${baseURL}/ai/chat`, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "Authorization": `Bearer ${token}`,
                    "Accept": "text/event-stream"
                },
                body: JSON.stringify({ messages: nextMessages })
            });

            if (!response.ok) {
                // Handle normal rate limiting 429 logic
                if (response.status === 429) {
                    const data = await response.json().catch(() => ({}));
                    const retryAfter = data?.retryAfterSeconds || 30;
                    setCountdown(retryAfter);
                    setLastFailedMessage(trimmed);

                    setMessages(prev => [
                        ...prev,
                        {
                            role: "ai",
                            content: `⏳ AI is currently busy. Your message is queued and will auto-retry in ~${retryAfter}s. You can also click "Retry" once the cooldown ends.`,
                            retryable: true,
                            retryPrompt: trimmed,
                        }
                    ]);
                    setIsLoading(false);
                    return;
                }
                throw new Error("API stream Error");
            }

            // Stream response setup
            nextMessages.push({ role: "ai", content: "" });
            setMessages([...nextMessages]);

            const reader = response.body?.getReader();
            const decoder = new TextDecoder("utf-8");

            if (reader) {
                let aiResponseContent = "";
                while (true) {
                    const { done, value } = await reader.read();
                    if (done) break;

                    const chunk = decoder.decode(value, { stream: true });
                    const lines = chunk.split('\\n\\n');

                    for (const line of lines) {
                        if (line.startsWith('data: ')) {
                            try {
                                const parsed = JSON.parse(line.replace('data: ', ''));
                                if (parsed.text) {
                                    aiResponseContent += parsed.text;
                                    
                                    // Progressive UI Update
                                    setMessages(prev => {
                                        const updated = [...prev];
                                        updated[updated.length - 1] = { role: "ai", content: aiResponseContent };
                                        return updated;
                                    });
                                }
                            } catch (e) {
                                // Ignore unparseable chunks
                            }
                        }
                    }
                }
            }

        } catch (err: unknown) {
            setMessages(prev => [...prev, {
                role: "ai",
                content: "Sorry, I had trouble processing that. Please try again."
            }]);
        } finally {
            setIsLoading(false);
        }
    }, [input, isLoading, messages]);

    const handleRetry = () => {
        if (lastFailedMessage && countdown <= 0) {
            sendMessage(lastFailedMessage);
        }
    };

    // Format countdown for display
    const formatTime = (seconds: number) => {
        const m = Math.floor(seconds / 60);
        const s = seconds % 60;
        return m > 0 ? `${m}m ${s}s` : `${s}s`;
    };

    return (
        <>
            {/* Floating Chat Bubble */}
            {!isOpen && (
                <button
                    onClick={() => setIsOpen(true)}
                    className="fixed bottom-6 right-6 z-50 bg-teal-600 hover:bg-teal-700 text-white p-4 rounded-full shadow-xl hover:shadow-2xl transition-all duration-300 hover:scale-110"
                    aria-label="Open Health Assistant"
                >
                    <MessageCircle size={24} />
                    <span className="absolute -top-1 -right-1 h-4 w-4 bg-emerald-400 rounded-full border-2 border-white animate-pulse" />
                </button>
            )}

            {/* Chat Window */}
            {isOpen && (
                <div className="fixed bottom-6 right-6 z-50 w-95 h-130 bg-white rounded-2xl shadow-2xl border border-slate-200 flex flex-col overflow-hidden animate-in slide-in-from-bottom-4">
                    {/* Header */}
                    <div className="bg-linear-to-r from-teal-600 to-teal-700 px-5 py-4 flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <div className="bg-white/20 p-2 rounded-lg">
                                <Bot size={20} className="text-white" />
                            </div>
                            <div>
                                <h3 className="text-white font-semibold text-sm">Health Assistant</h3>
                                <p className="text-teal-100 text-xs">
                                    {countdown > 0 ? `Cooldown: ${formatTime(countdown)}` : "Powered by Gemini AI"}
                                </p>
                            </div>
                        </div>
                        <button onClick={() => setIsOpen(false)} className="text-white/70 hover:text-white transition-colors">
                            <X size={20} />
                        </button>
                    </div>

                    {/* Messages */}
                    <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50">
                        {messages.map((msg, i) => (
                            <div key={i} className={`flex gap-2 ${msg.role === "user" ? "justify-end" : "justify-start"}`}>
                                {msg.role === "ai" && (
                                    <div className="w-7 h-7 rounded-full bg-teal-100 flex items-center justify-center shrink-0 mt-1">
                                        <Bot size={14} className="text-teal-600" />
                                    </div>
                                )}
                                <div
                                    className={`max-w-[85%] px-4 py-2.5 rounded-2xl text-sm leading-relaxed ${msg.role === "user"
                                        ? "bg-teal-600 text-white rounded-br-md"
                                        : msg.retryable
                                            ? "bg-amber-50 text-amber-800 border border-amber-200 rounded-bl-md shadow-sm"
                                            : "bg-white text-slate-700 border border-slate-200 rounded-bl-md shadow-sm"
                                        }`}
                                >
                                    {msg.role === "user" || msg.retryable ? (
                                        msg.content
                                    ) : (
                                        <ReactMarkdown
                                            remarkPlugins={[remarkGfm]}
                                            components={{
                                                p: ({ node, ...props }) => <p className="mb-2 last:mb-0" {...props} />,
                                                ul: ({ node, ...props }) => <ul className="list-disc pl-4 mb-2" {...props} />,
                                                ol: ({ node, ...props }) => <ol className="list-decimal pl-4 mb-2" {...props} />,
                                                li: ({ node, ...props }) => <li className="mb-1" {...props} />,
                                                strong: ({ node, ...props }) => <strong className="font-semibold text-slate-900" {...props} />,
                                                a: ({ node, ...props }) => <a className="text-teal-600 underline" {...props} />
                                            }}
                                        >
                                            {msg.content}
                                        </ReactMarkdown>
                                    )}
                                </div>
                                {msg.role === "user" && (
                                    <div className="w-7 h-7 rounded-full bg-slate-200 flex items-center justify-center shrink-0 mt-1">
                                        <User size={14} className="text-slate-600" />
                                    </div>
                                )}
                            </div>
                        ))}

                        {/* Loading indicator */}
                        {isLoading && (
                            <div className="flex gap-2 justify-start">
                                <div className="w-7 h-7 rounded-full bg-teal-100 flex items-center justify-center shrink-0">
                                    <Bot size={14} className="text-teal-600" />
                                </div>
                                <div className="bg-white border border-slate-200 px-4 py-3 rounded-2xl rounded-bl-md shadow-sm">
                                    <div className="flex gap-1.5">
                                        <span className="w-2 h-2 bg-teal-400 rounded-full animate-bounce" style={{ animationDelay: "0ms" }} />
                                        <span className="w-2 h-2 bg-teal-400 rounded-full animate-bounce" style={{ animationDelay: "150ms" }} />
                                        <span className="w-2 h-2 bg-teal-400 rounded-full animate-bounce" style={{ animationDelay: "300ms" }} />
                                    </div>
                                </div>
                            </div>
                        )}

                        {/* Countdown + Retry banner */}
                        {countdown > 0 && (
                            <div className="flex items-center gap-2 bg-amber-50 border border-amber-200 rounded-xl px-4 py-3 text-amber-700 text-sm">
                                <Clock size={16} className="shrink-0 animate-pulse" />
                                <span className="flex-1 font-medium">
                                    AI cooldown: <span className="font-bold text-amber-900">{formatTime(countdown)}</span>
                                </span>
                            </div>
                        )}

                        {/* Retry button - appears when cooldown ends */}
                        {countdown === 0 && lastFailedMessage && !isLoading && (
                            <button
                                onClick={handleRetry}
                                className="flex items-center gap-2 mx-auto bg-teal-50 hover:bg-teal-100 border border-teal-200 rounded-xl px-4 py-2.5 text-teal-700 text-sm font-medium transition-colors"
                            >
                                <RefreshCw size={14} />
                                Retry last message
                            </button>
                        )}

                        <div ref={messagesEndRef} />
                    </div>

                    {/* Input */}
                    <div className="p-3 bg-white border-t border-slate-100">
                        <div className="flex gap-2">
                            <input
                                type="text"
                                value={input}
                                onChange={(e) => setInput(e.target.value)}
                                onKeyDown={(e) => e.key === "Enter" && sendMessage()}
                                placeholder={countdown > 0 ? `AI cooldown... ${formatTime(countdown)}` : "Ask about your health..."}
                                className="flex-1 text-sm px-4 py-2.5 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-teal-200 bg-slate-50 disabled:opacity-60"
                                disabled={isLoading}
                            />
                            <button
                                onClick={() => sendMessage()}
                                disabled={isLoading || !input.trim()}
                                className="bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white p-2.5 rounded-xl transition-colors"
                            >
                                {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </>
    );
}

import axios, { AxiosResponse } from 'axios';
import { toast } from 'sonner';
import { ApiResponse } from '@ai-clinic/shared';

const api = axios.create({
    baseURL: process.env.NEXT_PUBLIC_API_URL || 'https://ai-clinic-backend.onrender.com/api/v1',
    withCredentials: true,
    headers: {
        'Content-Type': 'application/json',
    },
});

// Request interceptor to attach token
api.interceptors.request.use(
    (config) => {
        if (typeof window !== 'undefined') {
            // SEC-05 FIX: Read token directly (no JSON parsing needed)
            const token = localStorage.getItem('clinicToken');
            if (token) {
                config.headers.Authorization = `Bearer ${token}`;
            }
        }
        return config;
    },
    (error) => {
        return Promise.reject(error);
    }
);

// Response interceptor for global error handling
api.interceptors.response.use(
    (response) => {
        return response;
    },
    (error) => {
        let errorMessage = 'An unexpected error occurred';

        if (error.response) {
            errorMessage = error.response.data.message || error.response.data.error || 'Server Error';

            // Handle token expiration — auto-logout on 401
            if (error.response.status === 401) {
                if (typeof window !== 'undefined') {
                    localStorage.removeItem('clinicToken');
                    window.location.href = '/login';
                }
            }
        } else if (error.request) {
            errorMessage = 'Unable to connect to the server. Please check your connection.';
        }

        if (typeof window !== 'undefined') {
            toast.error(errorMessage);
        }

        return Promise.reject(error);
    }
);

export default api;
